INSERT INTO lr_questions (section_id, qid, preptest, section, question_number, question_type, stimulus, prompt, correct_choice, is_explained, source_note) SELECT s.id, $batch13$PT147-S4-Q10$batch13$, 147, 4, 10, $batch13$Sufficient Assumption$batch13$, $batch13$Journalist: Some critics argue that as the entertainment value of news reporting increases, the caliber of that reporting decreases. Yet the greatest journalists have been the most entertaining. So these critics are mistaken.$batch13$, $batch13$The journalist’s conclusion is properly drawn if which one of the following is assumed?$batch13$, $batch13$A$batch13$, true, $batch13$Batch 13; question text from local bank.$batch13$ FROM lr_sections s WHERE s.preptest=147 AND s.section=4 AND NOT EXISTS (SELECT 1 FROM lr_questions q WHERE q.qid=$batch13$PT147-S4-Q10$batch13$) ON CONFLICT DO NOTHING;
INSERT INTO lr_answer_choices (question_id, letter, choice_text, tag, is_correct) SELECT q.id, $batch13$A$batch13$, $batch13$The news reporting of the greatest journalists has been of the highest caliber.$batch13$, $batch13$Correct$batch13$, true FROM lr_questions q WHERE q.qid=$batch13$PT147-S4-Q10$batch13$ AND NOT EXISTS (SELECT 1 FROM lr_answer_choices c WHERE c.question_id=q.id AND c.letter=$batch13$A$batch13$) ON CONFLICT DO NOTHING;
INSERT INTO lr_answer_choices (question_id, letter, choice_text, tag, is_correct) SELECT q.id, $batch13$B$batch13$, $batch13$The greatest journalists have been entertainers who report the news.$batch13$, $batch13$Already Known$batch13$, false FROM lr_questions q WHERE q.qid=$batch13$PT147-S4-Q10$batch13$ AND NOT EXISTS (SELECT 1 FROM lr_answer_choices c WHERE c.question_id=q.id AND c.letter=$batch13$B$batch13$) ON CONFLICT DO NOTHING;
INSERT INTO lr_answer_choices (question_id, letter, choice_text, tag, is_correct) SELECT q.id, $batch13$C$batch13$, $batch13$Journalistic greatness involves producing news that is very valuable in some sense.$batch13$, $batch13$Too Weak$batch13$, false FROM lr_questions q WHERE q.qid=$batch13$PT147-S4-Q10$batch13$ AND NOT EXISTS (SELECT 1 FROM lr_answer_choices c WHERE c.question_id=q.id AND c.letter=$batch13$C$batch13$) ON CONFLICT DO NOTHING;
INSERT INTO lr_answer_choices (question_id, letter, choice_text, tag, is_correct) SELECT q.id, $batch13$D$batch13$, $batch13$Entertainment and news are not mutually exclusive categories.$batch13$, $batch13$Too Weak$batch13$, false FROM lr_questions q WHERE q.qid=$batch13$PT147-S4-Q10$batch13$ AND NOT EXISTS (SELECT 1 FROM lr_answer_choices c WHERE c.question_id=q.id AND c.letter=$batch13$D$batch13$) ON CONFLICT DO NOTHING;
INSERT INTO lr_answer_choices (question_id, letter, choice_text, tag, is_correct) SELECT q.id, $batch13$E$batch13$, $batch13$The worst journalists have been more entertaining than informative.$batch13$, $batch13$Irrelevant$batch13$, false FROM lr_questions q WHERE q.qid=$batch13$PT147-S4-Q10$batch13$ AND NOT EXISTS (SELECT 1 FROM lr_answer_choices c WHERE c.question_id=q.id AND c.letter=$batch13$E$batch13$) ON CONFLICT DO NOTHING;
INSERT INTO lr_explanations (question_id, style) SELECT q.id, 'single' FROM lr_questions q WHERE q.qid=$batch13$PT147-S4-Q10$batch13$ AND NOT EXISTS (SELECT 1 FROM lr_explanations e WHERE e.question_id=q.id AND e.style IN ('single','standard')) ON CONFLICT DO NOTHING;
INSERT INTO lr_explanation_steps (explanation_id, position, label, body) SELECT e.id, v.position, v.label, v.body FROM lr_explanations e JOIN lr_questions q ON q.id=e.question_id CROSS JOIN (VALUES (0, $batch13$Opposing Point$batch13$, $batch13$Critics say that as news reporting gets more entertaining, its caliber drops.$batch13$), (1, $batch13$Conclusion$batch13$, $batch13$The critics are mistaken.$batch13$), (2, $batch13$Evidence$batch13$, $batch13$The greatest journalists have been the most entertaining.$batch13$), (3, $batch13$Evaluate$batch13$, $batch13$To refute the critics, we need a case of maximum entertainment and high caliber together. We know the greatest journalists were the most entertaining. We don't yet know their reporting was of high caliber, since "great" could mean something else.$batch13$), (4, $batch13$Goal$batch13$, $batch13$The greatest journalists' reporting was of the highest caliber.$batch13$)) v(position,label,body) WHERE q.qid=$batch13$PT147-S4-Q10$batch13$ AND e.style='single' AND NOT EXISTS (SELECT 1 FROM lr_explanation_steps s WHERE s.explanation_id=e.id) ON CONFLICT DO NOTHING;
INSERT INTO lr_explanation_choice_notes (explanation_id, letter, body) SELECT e.id, v.letter, v.body FROM lr_explanations e JOIN lr_questions q ON q.id=e.question_id CROSS JOIN (VALUES ($batch13$A$batch13$, $batch13$The most entertaining reporting was also the highest caliber. That directly contradicts the critics.$batch13$), ($batch13$B$batch13$, $batch13$We already know the greatest journalists were entertaining. That says nothing about caliber.$batch13$), ($batch13$C$batch13$, $batch13$"Valuable in some sense" isn't the same as high caliber.$batch13$), ($batch13$D$batch13$, $batch13$The critics never said entertainment and news exclude each other. They said caliber drops as entertainment rises.$batch13$), ($batch13$E$batch13$, $batch13$The worst journalists don't tell us about the top of the scale.$batch13$)) v(letter,body) WHERE q.qid=$batch13$PT147-S4-Q10$batch13$ AND e.style='single' AND NOT EXISTS (SELECT 1 FROM lr_explanation_choice_notes n WHERE n.explanation_id=e.id AND n.letter=v.letter) ON CONFLICT DO NOTHING;
